def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """Cubic model that considers quadratic terms in gate and drain voltages."""
    return parameters[0] + parameters[1] * gate_voltage_abs + parameters[2] * drain_voltage_abs + parameters[3] * (gate_voltage_abs**2) + parameters[4] * (drain_voltage_abs**2) + parameters[5] * (gate_voltage_abs**3)
